<?php $overdue=array_filter($assignments,fn($item)=>$item['status']!=='done' && $item['due_date'] && $item['due_date']<date('Y-m-d')); if($overdue): ?><section class="card"><h2>Assignments needing attention</h2><?php foreach(array_slice($overdue,0,5) as $item): ?><div class="simple-row"><div><strong><?= e($item['title']) ?></strong><small><?= e($item['module']) ?></small></div><span class="error-text">Overdue &middot; <?= e($item['due_date']) ?></span></div><?php endforeach; ?><p class="footnote"><a href="/uni?view=assignments">Open assignments</a></p></section><?php endif; ?>
